// generated by `cargo xtask protocol` from crates/kiln-protocol, do not edit
import type { GridCompletion } from "./GridCompletion";
import type { GridFormulaHint } from "./GridFormulaHint";
import type { GridRefSpan } from "./GridRefSpan";
import type { Rect } from "./Rect";

/**
 * The in-cell editor.
 */
export type GridEditor = { 
/**
 * The entry.
 */
text: string, 
/**
 * Selection start, UTF-16.
 */
start: number, 
/**
 * Selection end (caret), UTF-16.
 */
end: number, 
/**
 * Coloured references.
 */
refs: Array<GridRefSpan>, 
/**
 * Autocomplete suggestions (functions, names, column values).
 */
completions: Array<GridCompletion>, 
/**
 * The highlighted suggestion.
 */
completion_index: number, 
/**
 * Inline AutoComplete text after the caret (shown selected), for text entries.
 */
inline_completion: string | null, 
/**
 * The argument tooltip.
 */
hint: GridFormulaHint | null, 
/**
 * The editor box on the surface (CSS pixels), for the input proxy and popovers.
 */
rect: Rect, 
/**
 * The caret on the surface (CSS pixels).
 */
caret: Rect, 
/**
 * The pick list (Alt+Down), when open.
 */
pick_list: Array<string> | null, 
/**
 * The formula bar is the one editing.
 */
formula_bar: boolean, };
